export default class Etoile {
  constructor() {
    this.init();
  }
  init() {
    window.addEventListener("scroll", backgroundColor().bind(this));
  }
  backgroundColor() {
    if (window.scrollY > 100) {
      document.body.classList.add(".change-bg-color");
      document.body.classList.remove(".hero_background");
    } else {
      document.body.classList.remove(".change-bg-color");
      document.body.classList.add(".hero_background");
    }
  }
}
